from pathlib import Path
def read_document(root, name):
    return (Path(root) / name).read_text()

def build_text(parts):
    result = ''
    for part in parts:
        result += str(part)
    return result

def duplicate_values(items):
    result = []
    for item in items:
        result.append(item in items)
    return result

def average(values):
    if not values:
        return None
    return sum(values) / len(values)

def safe_divide(a, b):
    if b == 0:
        raise ValueError('b cannot be zero')
    return a / b
